package app.noir.mobile;
import android.app.*;
import android.content.*;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;

public final class TvSettingsActivity extends Activity {
    LinearLayout body;TextView feedback,pc,stream,copyStatus;View first,copyRow;boolean busy;final Map<String,TextView> values=new HashMap<>();
    static final String[] QUALITY_NAMES={"Auto (fits this TV and connection)","Up to 1080p","Up to 4K (no remux)","Best available (allows remux)"};
    static {String[][] words={{"Stream quality","جودة البث"},{"Auto (fits this TV and connection)","تلقائي (يناسب التلفزيون والاتصال)"},{"Up to 1080p","حتى 1080p"},{"Up to 4K (no remux)","حتى 4K (دون remux)"},{"Best available (allows remux)","أفضل جودة متاحة (يسمح بـ remux)"},{"TV check","فحص التلفزيون"},{"Not tested","لم يُختبر"},{"Copy stream link from my PC","نسخ رابط البث من الكمبيوتر"},{"%.1f Mbit/s","%.1f ميغابت/ث"}};for(String[] p:words)Loc.AR.put(p[0],p[1]);}
    static {String[][] words={{"TV settings","إعدادات التلفزيون"},{"Playback","التشغيل"},{"Audio passthrough","تمرير الصوت"},{"Only if your TV or soundbar supports Dolby/DTS","فقط إذا كان التلفزيون أو جهاز الصوت يدعم Dolby/DTS"},{"Match frame rate","مطابقة معدل الإطارات"},{"Seek step","مدة التقديم والإرجاع"},{"10 s","١٠ ث"},{"15 s","١٥ ث"},{"30 s","٣٠ ث"},{"Subtitle language","لغة الترجمة"},{"Skip intro","تخطي المقدمة"},{"Show button","إظهار زر التخطي"},{"Skip automatically","التخطي تلقائيًا"},{"On","تشغيل"},{"Off","إيقاف"},{"PC","الكمبيوتر"},{"Paired PC","الكمبيوتر المقترن"},{"Not paired","غير مقترن"},{"Sync now","المزامنة الآن"},{"Pair again","الاقتران مجددًا"},{"Unpair","إلغاء الاقتران"},{"Unpair this TV?","إلغاء اقتران هذا التلفزيون؟"},{"This disconnects all TV profiles from the PC. Saved history stays on this TV.","يفصل هذا جميع ملفات التلفزيون عن الكمبيوتر. يبقى السجل محفوظًا على التلفزيون."},{"Syncing…","جارٍ المزامنة…"},{"Sync complete","اكتملت المزامنة"},{"Couldn't sync. Keep Noir open on the paired PC and check Wi-Fi.","تعذرت المزامنة. أبقِ نوار مفتوحًا على الكمبيوتر المقترن وتحقق من واي فاي."},{"Unpairing…","جارٍ إلغاء الاقتران…"},{"TV disconnected","تم فصل التلفزيون"},{"Couldn't disconnect. Try again.","تعذر الفصل. حاول مجددًا."},{"Streaming","البث"},{"Set","تم الضبط"},{"Not set","غير مضبوط"},{"Profiles","الملفات"},{"Switch profile","تبديل الملف"},{"About","حول"},{"Version","الإصدار"},{"TV","تلفزيون"},{"English","الإنجليزية"},{"Arabic","العربية"},{"Stream link saved","تم حفظ رابط البث"},{"Stream link cleared","تم مسح رابط البث"},{"Couldn't clear stream link.","تعذر مسح رابط البث."},{"PC connection","اتصال الكمبيوتر"},{"Can't reach the PC right now","تعذر الوصول إلى الكمبيوتر حاليًا"}};for(String[] p:words)Loc.AR.put(p[0],p[1]);}
    String t(String s){return TvSetupActivity.t(s);}
    DataStore data(){return NoirApp.data;}
    @Override protected void onCreate(Bundle b){super.onCreate(b);FrameLayout root=TvUi.screen(this);ScrollView scroll=new ScrollView(this);scroll.setClipToPadding(false);body=TvSetupActivity.column(this);scroll.addView(body);root.addView(scroll);body.addView(TvUi.text(this,t("TV settings"),30,TvUi.WHITE,true));
        group("Playback");row("passthrough","Audio passthrough","Only if your TV or soundbar supports Dolby/DTS",()->{TvPrefs.passthrough(this,!TvPrefs.passthrough(this));refreshPlayback();});row("frame","Match frame rate","",()->{TvPrefs.matchFrameRate(this,!TvPrefs.matchFrameRate(this));refreshPlayback();});row("seek","Seek step","",()->{int s=TvPrefs.seekStep(this);TvPrefs.seekStep(this,s==10?15:s==15?30:10);refreshPlayback();});
        row("subtitles","Subtitle language","",()->{String[] choices={"English","Arabic","Off"};choose("Subtitle language",choices,Arrays.asList(choices).indexOf(data().defaultSubtitleLanguage()),n->{data().phoneSetting("subtitles",choices[n]);refreshPlayback();});});
        row("intro","Skip intro","",()->{String[] names={"Show button","Skip automatically","Off"};choose("Skip intro",names,Arrays.asList(PlayerPrefs.MODES).indexOf(PlayerPrefs.mode(data(),"intro")),n->{PlayerPrefs.mode(data(),"intro",PlayerPrefs.MODES[n]);refreshPlayback();});});
        group("PC");pc=TvUi.text(this,"",15,TvUi.MUTED,false);pc.setPadding(TvUi.dp(this,10),TvUi.dp(this,8),0,TvUi.dp(this,8));body.addView(pc);row("sync","Sync now","",this::sync);row("pair","Pair again","",()->TvSetupActivity.pair(this,()->{refreshPc();feedback.setText(t("Sync complete"));}));row("unpair","Unpair","",this::confirmUnpair);
        group("Streaming");row("quality","Stream quality","",()->choose("Stream quality",QUALITY_NAMES,Arrays.asList(TvPrefs.QUALITIES).indexOf(TvPrefs.quality(this)),n->{TvPrefs.quality(this,TvPrefs.QUALITIES[n]);refreshStreaming();}));row("check","TV check","",()->startActivity(new Intent(this,TvCheckActivity.class)));stream=row("stream","Stream link","",()->TvSetupActivity.stream(this,()->{refreshStream();feedback.setText(t("Stream link saved"));}));TextView copy=row("copy","Copy stream link from my PC","",this::copyStream);copyRow=(View)copy.getParent();copyStatus=TvSetupActivity.status(this,body);copyStatus.setVisibility(View.GONE);row("clear","Clear stream link","",this::clearStream);
        group("Profiles");row("profile","Switch profile","",()->startActivity(new Intent(this,TvProfilesActivity.class)));
        group("About");String version="";try{version=getPackageManager().getPackageInfo(getPackageName(),0).versionName;}catch(android.content.pm.PackageManager.NameNotFoundException ignored){}TextView about=TvUi.text(this,t("Version")+" "+version+" · "+t("TV"),15,TvUi.MUTED,false);about.setPadding(TvUi.dp(this,10),TvUi.dp(this,12),0,TvUi.dp(this,12));body.addView(about);feedback=TvSetupActivity.status(this,body);setContentView(root);Loc.apply(this);refreshPlayback();refreshPc();refreshStreaming();first.requestFocus();
    }
    @Override protected void onResume(){super.onResume();if(body!=null){refreshPc();refreshStreaming();refreshStream();}}
    void group(String title){TextView label=TvUi.text(this,t(title),19,TvUi.GOLD,true);label.setPadding(TvUi.dp(this,10),TvUi.dp(this,20),0,TvUi.dp(this,8));body.addView(label);}
    TextView row(String key,String title,String note,Runnable action){LinearLayout line=new LinearLayout(this);line.setGravity(Gravity.CENTER_VERTICAL);line.setPadding(TvUi.dp(this,16),TvUi.dp(this,12),TvUi.dp(this,16),TvUi.dp(this,12));line.setMinimumHeight(TvUi.dp(this,56));LinearLayout labels=new LinearLayout(this);labels.setOrientation(LinearLayout.VERTICAL);labels.addView(TvUi.text(this,t(title),17,TvUi.WHITE,true));if(!note.isEmpty()){TextView sub=TvUi.text(this,t(note),13,TvUi.MUTED,false);sub.setPadding(0,TvUi.dp(this,5),0,0);labels.addView(sub);}line.addView(labels,new LinearLayout.LayoutParams(0,-2,1));TextView value=TvUi.text(this,"",16,TvUi.GOLD,false);value.setGravity(Gravity.END);value.setPadding(TvUi.dp(this,20),0,0,0);line.addView(value,new LinearLayout.LayoutParams(-2,-2));TvUi.focusable(line,TvUi.PANEL,TvUi.dp(this,10));line.setOnClickListener(v->{if(!busy)action.run();});line.setContentDescription(t(title));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(TvUi.dp(this,10),TvUi.dp(this,6),TvUi.dp(this,10),TvUi.dp(this,6));body.addView(line,lp);values.put(key,value);if(first==null)first=line;return value;}
    void value(String key,String v){values.get(key).setText(v);}
    void refreshPlayback(){value("passthrough",t(TvPrefs.passthrough(this)?"On":"Off"));value("frame",t(TvPrefs.matchFrameRate(this)?"On":"Off"));value("seek",t(TvPrefs.seekStep(this)+" s"));value("subtitles",t(data().defaultSubtitleLanguage()));String mode=PlayerPrefs.mode(data(),"intro");value("intro",t(mode.equals(PlayerPrefs.AUTO)?"Skip automatically":mode.equals(PlayerPrefs.OFF)?"Off":"Show button"));}
    void refreshPc(){boolean paired=data().paired();JSONObject s=data().settings();String name=s.optString("hostName",s.optString("pcName",data().address()));String state=data().lastSyncState();if(state.matches("(?is).*(failed to connect|timed? ?out|unreachable|refused|exception|/[0-9]+\\.[0-9]+).*"))state="Can't reach the PC right now";pc.setText(paired?t("Paired PC")+" · "+name+"\n"+t(state):t("Not paired"));value("pair",t(paired?"Pair again":"Pair with your PC"));copyRow.setVisibility(paired?View.VISIBLE:View.GONE);}
    void refreshStreaming(){value("quality",t(QUALITY_NAMES[Arrays.asList(TvPrefs.QUALITIES).indexOf(TvPrefs.quality(this))]));float mbps=TvPrefs.mbps(this);value("check",mbps>0?Loc.f("%.1f Mbit/s",mbps):t("Not tested"));}
    void copyStream(){if(busy||!data().paired())return;busy=true;TvSetupActivity.copyFromPc(this,data(),message->{copyStatus.setVisibility(View.VISIBLE);copyStatus.setText(t(message));copyStatus.post(()->copyStatus.requestRectangleOnScreen(new android.graphics.Rect(0,0,copyStatus.getWidth(),copyStatus.getHeight()),false));if(!message.equals("Confirm on your PC · up to 2 minutes…")){busy=false;refreshStream();}},config->{});}
    void refreshStream(){DataStore source=data();value("stream",t("Loading…"));source.network.execute(()->{try{boolean set=!new PhoneDownloadSettings(source.context).load().optString("manifest").isEmpty();runOnUiThread(()->{if(!isDestroyed()&&!isFinishing()&&source==data())value("stream",t(set?"Set":"Not set"));});}catch(Exception e){runOnUiThread(()->{if(!isDestroyed()&&!isFinishing())value("stream",t("Couldn't load stream settings."));});}});}
    interface Choice {void run(int n);}
    void choose(String title,String[] labels,int selected,Choice action){String[] translated=new String[labels.length];for(int n=0;n<labels.length;n++)translated[n]=t(labels[n]);AlertDialog d=new AlertDialog.Builder(this).setTitle(t(title)).setSingleChoiceItems(translated,selected,(x,n)->{action.run(n);x.dismiss();}).setNegativeButton(t("Cancel"),null).create();d.setOnShowListener(v->{d.getListView().requestFocus();if(selected>=0)d.getListView().setSelection(selected);});d.show();}
    void sync(){if(!data().paired()){TvSetupActivity.pair(this,this::refreshPc);return;}DataStore source=data();busy=true;value("sync",t("Syncing…"));source.network.execute(()->{String result;try{source.sync();result="Sync complete";}catch(Exception e){result="Couldn't sync. Keep Noir open on the paired PC and check Wi-Fi.";}String message=result;runOnUiThread(()->{busy=false;if(isDestroyed()||isFinishing())return;value("sync",t(message));refreshPc();});});}
    void confirmUnpair(){if(!data().paired()){feedback.setText(t("Not paired"));return;}AlertDialog d=new AlertDialog.Builder(this).setTitle(t("Unpair this TV?")).setMessage(t("This disconnects all TV profiles from the PC. Saved history stays on this TV.")).setNegativeButton(t("Cancel"),null).setPositiveButton(t("Unpair"),(x,w)->{busy=true;value("unpair",t("Unpairing…"));DataStore source=data();source.network.execute(()->{String result;try{unpairAll(source);result="TV disconnected";}catch(Exception e){result="Couldn't disconnect. Try again.";}String message=result;runOnUiThread(()->{busy=false;if(isDestroyed()||isFinishing())return;value("unpair","");feedback.setText(t(message));refreshPc();});});}).create();d.setOnShowListener(v->d.getButton(-2).requestFocus());d.show();}
    // There is no phone unpair UI. Clear every profile's cached credentials and the shared peer,
    // retaining libraries and PC profile bindings so history cannot attach to an unrelated PC.
    static void unpairAll(DataStore source)throws Exception{synchronized(NoirApp.class){List<DataStore> stores=new ArrayList<>();for(JSONObject p:DataStore.objects(source.profiles.list()))stores.add(NoirApp.dataFor(source.context,p.optString("id")));source.rememberPeer("","","");JSONObject peer=new JSONObject(new String(source.peerFile().readFully(),java.nio.charset.StandardCharsets.UTF_8));if(!peer.optString("token").isEmpty())throw new java.io.IOException("Couldn't disconnect. Try again.");for(DataStore store:stores){synchronized(store){for(String key:new String[]{"address","pin","token"})store.stateObject(key,null);store.online=false;store.connection="Not paired";store.stateObject("lastSyncState",null);}}DataStore.flushWrites();for(DataStore store:stores)store.flush();}}
    void clearStream(){AlertDialog d=new AlertDialog.Builder(this).setTitle(t("Clear the saved stream link?")).setNegativeButton(t("Cancel"),null).setPositiveButton(t("Clear"),(x,w)->{DataStore source=data();busy=true;source.network.execute(()->{String result;try{PhoneDownloadSettings storage=new PhoneDownloadSettings(source.context);JSONObject config=storage.load();DataStore.put(config,"manifest","");storage.save(config);result="Stream link cleared";}catch(Exception e){result="Couldn't clear stream link.";}String message=result;runOnUiThread(()->{busy=false;if(isDestroyed()||isFinishing())return;feedback.setText(t(message));refreshStream();});});}).create();d.setOnShowListener(v->d.getButton(-2).requestFocus());d.show();}
}
